// Uses only the synthetic fixture generated by dashboard-comparison.test.ts.
import { execFileSync } from 'node:child_process';
import { readFileSync, writeFileSync, mkdtempSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';
const directory=mkdtempSync(join(tmpdir(),'fintrack-comparison-'));
const html=readFileSync(process.argv[2]||'/tmp/fintrack-comparison.html','utf8');
const checks=`<script>
(async()=>{
 const check=(ok,message)=>{if(!ok)throw new Error(message)},tick=()=>new Promise(r=>setTimeout(r,0)),get=id=>document.getElementById(id);
 const set=(id,value)=>{const n=get(id);n.value=value;n.dispatchEvent(new Event(n.type==='search'?'input':'change'));};
 const amounts=()=>[...document.querySelectorAll('#comparison-table tfoot [data-amount]')].map(n=>Number(n.dataset.amount));
 const equal=(actual,expected,message)=>check(JSON.stringify(actual)===JSON.stringify(expected),message+': '+JSON.stringify(actual));
 const overflow=()=>check(document.documentElement.scrollWidth<=innerWidth+1,'Page overflows viewport');
 await tick();await document.fonts.ready;check(!get('app').hidden,'Dashboard did not load');overflow();
 const edit=document.querySelector('#rows .record-tools a');check(edit?.href.startsWith('https://t.me/test_bot?start=edit_expense_'),'Record edit link missing or incorrect');
 const snapshot=JSON.stringify(JSON.parse(get('bootstrap').textContent).data.records);
 document.querySelector('[data-open-view=compare]').click();
 check(!get('report-filters').hidden,'Comparison filters hidden');
 equal(amounts(),[10000,37500,0,15100],'Monthly totals');
 check(document.querySelectorAll('#comparison-table tbody tr').length===3,'Category rows missing');
 set('comparison-group','item');
 const coffee=[...document.querySelectorAll('#comparison-table tbody tr')].find(n=>n.querySelector('button').textContent.trim().toLowerCase()==='coffee');
 equal([...coffee.querySelectorAll('[data-amount]')].map(n=>Number(n.dataset.amount)),[10000,15000,0,5000],'Item normalization');
 check(coffee.textContent.includes('+50.0%'),'Month change missing');
 check(get('comparison-table').textContent.includes('<'+'/script><img'),'Hostile label was not rendered as literal text');
 check(!get('comparison-table').querySelector('img'),'Unsafe label created markup');
 const month=()=>[...document.querySelectorAll('.comparison-months input')];month().find(n=>n.value==='2026-02').click();
 equal(amounts(),[10000,0,15100],'Month exclusion');
 for(const key of ['2026-01','2026-03','2026-04'])month().find(n=>n.value===key).click();
 check(get('compare-content').textContent.includes('Select a month'),'Empty month selection needs recovery');
 [...document.querySelectorAll('.comparison-tools button')].find(b=>b.textContent==='Use full snapshot').click();await tick();
 equal(amounts(),[10000,37500,0,15100],'Full snapshot reset');
 document.querySelector('.scope-panel').open=true;
 set('scope-items-search','coffee');const pick=()=>document.querySelector('#scope-items-options input');pick().click();
 equal(amounts(),[0,22500,0,10100],'Exact item exclusion');
 set('scope-items-mode','include');equal(amounts(),[10000,15000,0,5000],'Exact item inclusion');
 check(get('total-expense').textContent==='300 ֏','Overview totals ignore item selection');
 set('scope-categories-search','Transport');document.querySelector('#scope-categories-options input').click();
 equal(amounts(),[10000,15000,0,0],'Combined category and item filters');
 set('scope-categories-mode','include');equal(amounts(),[0,0,0,5000],'Combined include filters');
 get('reset').click();equal(amounts(),[10000,37500,0,15100],'Clear all filters');
 set('scope-items-mode','include');check(get('compare-content').textContent.includes('No spending matches'),'Empty include selection incorrectly includes everything');
 get('reset').click();
 document.querySelector('[data-open-view=overview]').click();
 document.querySelector('#rows .record-tools button').click();check(get('total-expense').textContent==='625 ֏','Single record exclusion failed');
 check(get('scope-excluded').textContent.includes('Restore 1'),'Excluded record cannot be restored');
 get('scope-excluded').querySelector('button').click();check(get('total-expense').textContent==='626 ֏','Single record restore failed');
 set('scope-items-search','coffee');pick().click();
 let csvBlob;const originalCreate=URL.createObjectURL,originalClick=HTMLAnchorElement.prototype.click;
 URL.createObjectURL=blob=>{csvBlob=blob;return 'blob:test'};HTMLAnchorElement.prototype.click=function(){};
 get('csv').click();const csv=await csvBlob.text();check(!csv.toLowerCase().includes('coffee'),'CSV includes excluded items');check(csv.includes('Lunch'),'CSV omits included items');
 URL.createObjectURL=originalCreate;HTMLAnchorElement.prototype.click=originalClick;get('reset').click();
 document.querySelector('[data-open-view=compare]').click();
 get('from').value='2026-01-05';get('to').value='2026-04-12';get('apply').click();await tick();
 check(get('comparison-table').textContent.includes('Partial month'),'Partial months are not labeled');
 set('comparison-align','same');equal(amounts(),[10000,17500,0,15000],'Same-day monthly comparison');
 const before=amounts();window.dispatchEvent(new Event('beforeprint'));
 check(!document.querySelector('[data-view=compare]').hidden,'Printing switches away from comparison');equal(amounts(),before,'Printing changes comparison');
 window.dispatchEvent(new Event('afterprint'));check(get('comparison-align').value==='same','Printing loses comparison controls');
 get('from').value='2026-01-25';get('to').value='2026-02-10';get('apply').click();await tick();
 check(get('compare-content').textContent.includes('no overlapping days'),'Incompatible partial months silently show zero');
 set('comparison-align','all');[...document.querySelectorAll('.comparison-tools button')].find(b=>b.textContent==='Use full snapshot').click();await tick();
 set('comparison-group','item');document.querySelector('.scope-panel').open=false;overflow();
 const beforeSnapshot=JSON.stringify(JSON.parse(get('bootstrap').textContent).data.records);check(snapshot===beforeSnapshot,'Filtering mutated original data');
 document.querySelector('#comparison-table tbody button').click();
 check(!get('view-overview').hidden,'Comparison row does not open records');
 check(get('row-count').textContent.startsWith('3 records'),'Comparison drill-down does not use exact item filter');
 get('reset').click();document.querySelector('[data-open-view=compare]').click();overflow();window.scrollTo(0,0);
 document.documentElement.dataset.browserTest='passed';
})().catch(e=>{document.documentElement.dataset.browserTest='failed: '+e.message});
</script>`;
const path=join(directory,'index.html');writeFileSync(path,html.replace('</body>',checks+'</body>'));
for(const [name,size]of [['desktop','1440,1100'],['mobile','390,844']]){
 const output=execFileSync('chromium',['--headless','--no-sandbox','--disable-gpu','--disable-dev-shm-usage',`--user-data-dir=${join(directory,name)}`,`--window-size=${size}`,'--virtual-time-budget=4000',`--screenshot=/tmp/fintrack-comparison-${name}.png`,'--dump-dom','file://'+path],{encoding:'utf8',maxBuffer:8*1024*1024,stdio:['ignore','pipe','ignore']});
 const result=output.match(/data-browser-test="([^"]+)"/)?.[1];
 if(result!=='passed')throw new Error(name+': '+(result||'No test result'));
 console.log(name+': category/item/record inclusion and exclusion, monthly comparisons, partial months, CSV, editing links, print and drill-down passed.');
}
